"""Execute the C runtime against fixtures generated by the application's real encoders."""
import argparse
import base64
import ctypes
import datetime
import json
import pathlib
import subprocess

parser = argparse.ArgumentParser()
parser.add_argument('--output', type=pathlib.Path, required=True)
args = parser.parse_args()
root = pathlib.Path(__file__).resolve().parents[2]
if args.output.exists() and any(args.output.iterdir()):
    raise SystemExit('Use a new or verified empty task-owned output directory')
args.output.mkdir(parents=True, exist_ok=True)
libfile = args.output / 'libxsuite.so'
subprocess.run(['cc', '-std=c11', '-Wall', '-Wextra', '-Werror', '-fPIC', '-shared', '-I' + str(root / 'core'),
                str(root / 'core/xsuite/xsuite_packet.c'), '-o', str(libfile)], check=True)
lib = ctypes.CDLL(str(libfile))
lib.xsuite_packet.argtypes = [ctypes.c_uint8, ctypes.c_bool, ctypes.c_int32, ctypes.c_int32, ctypes.c_uint32,
                             ctypes.c_uint32, ctypes.c_uint32, ctypes.c_bool, ctypes.c_void_p, ctypes.c_size_t]
lib.xsuite_packet.restype = ctypes.c_size_t
lib.xsuite_packet_edit.argtypes = lib.xsuite_packet.argtypes[:-2] + [ctypes.c_char_p, ctypes.c_uint16, ctypes.c_uint8] + lib.xsuite_packet.argtypes[-2:]
lib.xsuite_packet_edit.restype = ctypes.c_size_t
fixtures = json.loads((root / 'tests/host/xsuite-fixtures.json').read_text())
for f in fixtures:
    buf = ctypes.create_string_buffer(257)
    fn = lib.xsuite_packet_edit if f['editing'] else lib.xsuite_packet
    params = [f['action'], f['loc'], round(f.get('lat', 0) * 1e7), round(f.get('lon', 0) * 1e7),
              f['t'] // 60000, 0x12345678, 0x89abcdef, False]
    if f['editing']: params += [f.get('note', 'XSUITE_EDIT_SLOT').encode(), f.get('qty', 0x1234), f.get('pri', 2)]
    n = fn(*params, buf, len(buf))
    expect = f"X1.{f['template']}.C.1234567889ABCDEF.1/1.{f['payload']}".encode()
    assert n == len(expect) and buf.value == expect, (f, buf.value, expect)
    for cap in (1, len(expect) - 1, len(expect)):
        guarded = ctypes.create_string_buffer(b'X' * 300)
        assert fn(*params, guarded, cap) == 0
        assert guarded.raw == b'X' * 300 + b'\0', 'Rejected short buffer modified output'
buf = ctypes.create_string_buffer(257)
assert lib.xsuite_packet(0, False, 0, 0, 1, 1, 1, False, buf, 257) == 0
assert lib.xsuite_packet(0, True, 900000001, 0, 1, 1, 1, False, buf, 257) == 0
assert lib.xsuite_packet(255, True, 0, 0, 1, 1, 1, False, buf, 257) == 0
assert lib.xsuite_packet(1, False, 0, 0, 0, 1, 1, False, buf, 257) > 0
assert lib.xsuite_packet(0, True, -12345650, 23456750, 1, 1, 1, True, buf, 257)
payload = base64.urlsafe_b64decode(buf.value.split(b'.')[-1] + b'==')
assert int.from_bytes(payload[3:7], 'big', signed=True) == -123456
assert int.from_bytes(payload[7:11], 'big', signed=True) == 234568
assert payload[15] == 1
lib.xsuite_unix_minutes.argtypes = [ctypes.c_uint32, ctypes.c_uint32]
lib.xsuite_unix_minutes.restype = ctypes.c_uint32
for date in (datetime.datetime(2000, 1, 1), datetime.datetime(2024, 2, 29, 12, 30), datetime.datetime(2026, 11, 22, 14, 45)):
    actual = lib.xsuite_unix_minutes(int(date.strftime('%d%m%y')), int(date.strftime('%H%M%S')))
    assert actual == int(date.replace(tzinfo=datetime.timezone.utc).timestamp()) // 60, (date, actual)
assert lib.xsuite_unix_minutes(0, 0) == 0
print(f'PASS: {len(fixtures)} canonical C/TypeScript fixtures, output bounds, GPS rounding, SOS and UTC')
